import { handleCors, jsonResponse, errorResponse } from "../_shared/cors.ts";
import { verifyAdminKey } from "../_shared/mesa.ts";
import { createServiceClient } from "../_shared/supabase.ts";

Deno.serve(async (req) => {
  const cors = handleCors(req);
  if (cors) return cors;

  try {
    verifyAdminKey(req);
    const supabase = createServiceClient();

    const { data, error } = await supabase
      .from("cola_reproduccion")
      .select("*, mesas(numero_mesa)")
      .in("estado", ["pendiente", "reproduciendo"])
      .order("creado_en", { ascending: true });

    if (error) throw error;

    const canciones = (data ?? []).map((c, idx) => ({
      id: c.id,
      mesa_id: c.mesa_id,
      numero_mesa: c.mesas?.numero_mesa,
      youtube_video_id: c.youtube_video_id,
      titulo_cancion: c.titulo_cancion,
      nombre_cliente: c.nombre_cliente,
      saludo: c.saludo,
      estado: c.estado,
      creado_en: c.creado_en,
      posicion: idx + 1,
    }));

    return jsonResponse(canciones);
  } catch (e) {
    const msg = e instanceof Error ? e.message : "error";
    if (msg === "admin_no_autorizado") return errorResponse(msg, "No autorizado.", 403);
    return errorResponse("error", "Error al obtener cola.", 500);
  }
});

export const corsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": Deno.env.get("ALLOWED_ORIGIN") ?? "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-mesa-token, x-admin-key",
  "Access-Control-Allow-Methods": "GET, POST, PATCH, OPTIONS",
};

export function handleCors(req: Request): Response | null {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }
  return null;
}

export function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

export function errorResponse(
  code: string,
  detail: string,
  status: number,
): Response {
  return jsonResponse({ error: code, detail }, status);
}

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.1";

export function createServiceClient() {
  return createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    { auth: { persistSession: false, autoRefreshToken: false } },
  );
}

import { createServiceClient } from "./supabase.ts";

export interface Mesa {
  id: number;
  numero_mesa: number;
  token_seguridad: string;
  activa: boolean;
}

export async function obtenerMesaPorNumero(
  numeroMesa: number,
): Promise<Mesa | null> {
  const supabase = createServiceClient();
  const { data, error } = await supabase
    .from("mesas")
    .select("id, numero_mesa, token_seguridad, activa")
    .eq("numero_mesa", numeroMesa)
    .maybeSingle();

  if (error) throw error;
  return data;
}

export async function validarMesaToken(
  numeroMesa: number,
  token: string,
): Promise<Mesa> {
  const mesa = await obtenerMesaPorNumero(numeroMesa);
  if (!mesa || !mesa.activa) {
    throw new Error("mesa_no_encontrada");
  }
  if (token !== mesa.token_seguridad) {
    throw new Error("token_invalido");
  }
  return mesa;
}

export function verifyAdminKey(req: Request): void {
  const key = req.headers.get("x-admin-key");
  const expected = Deno.env.get("ADMIN_API_KEY");
  if (!key || !expected || key !== expected) {
    throw new Error("admin_no_autorizado");
  }
}

const TIMEZONE = "America/Lima";
const HORA_INICIO = "17:30";
const HORA_FIN = "02:00";

function parseMinutos(hora: string): number {
  const [h, m] = hora.split(":").map(Number);
  return h * 60 + m;
}

export function karaokeEstaAbierto(): boolean {
  if (Deno.env.get("KARAOKE_IGNORAR_HORARIO") === "true") return true;

  const ahora = new Date(
    new Date().toLocaleString("en-US", { timeZone: TIMEZONE }),
  );
  const minutos = ahora.getHours() * 60 + ahora.getMinutes();
  const inicio = parseMinutos(HORA_INICIO);
  const fin = parseMinutos(HORA_FIN);

  if (inicio > fin) return minutos >= inicio || minutos < fin;
  return minutos >= inicio && minutos < fin;
}

export function validarHorario(): void {
  if (!karaokeEstaAbierto()) {
    throw new Error(`fuera_de_horario:${HORA_INICIO}:${HORA_FIN}`);
  }
}

export function estadoHorario() {
  return {
    abierto: karaokeEstaAbierto(),
    horario: { inicio: HORA_INICIO, fin: HORA_FIN, zona_horaria: TIMEZONE },
    limite_canciones_por_mesa: 5,
    total_mesas: 12,
  };
}

const PALABRAS_BLOQUEADAS = new Set([
  "puto", "puta", "mierda", "pendejo", "pendeja", "culero", "culera",
  "idiota", "estupido", "estupida", "imbecil", "maricon", "marica",
  "hijueputa", "gonorrea", "malparido", "malparida", "hp", "ctm",
  "concha", "coño", "carajo", "verga", "pene", "vagina", "sexo",
  "pornografia", "porno", "nazi", "hitler",
]);

function normalizar(texto: string): string {
  return texto
    .toLowerCase()
    .replace(/0/g, "o").replace(/1/g, "i").replace(/3/g, "e")
    .replace(/4/g, "a").replace(/5/g, "s").replace(/7/g, "t")
    .replace(/@/g, "a").replace(/\$/g, "s")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

export function contieneContenidoOfensivo(texto: string): boolean {
  const tokens = normalizar(texto).match(/[a-zñ]+/g) ?? [];
  for (const token of tokens) {
    if (PALABRAS_BLOQUEADAS.has(token)) return true;
    for (const palabra of PALABRAS_BLOQUEADAS) {
      if (palabra.length >= 4 && token.includes(palabra)) return true;
    }
  }
  return false;
}

export function filtrarTexto(texto: string, campo: string): string {
  const limpio = texto.trim();
  if (contieneContenidoOfensivo(limpio)) {
    throw new Error(`contenido_no_permitido:${campo}`);
  }
  return limpio;
}
